cat > middleware/crow_flush_integration_test.go <<'EOF'
package middleware_test

import (
 "bytes"
 "fmt"
 "io"
 "net/http"
 "net/http/httptest"
 "testing"

 "github.com/go-chi/chi/v5/middleware"
)

func TestCrowDiscardFlushIntegration(t *testing.T) {
 for _, h2 := range []bool{false,true} {
 for _, method := range []string{"GET","HEAD"} {
 for _, controller := range []bool{false,true} {
 for _, informational := range []bool{false,true} {
 for _, discard := range []bool{false,true} {
  t.Run(fmt.Sprintf("h2=%v/%s/controller=%v/info=%v/discard=%v", h2,method,controller,informational,discard), func(t *testing.T) {
   s := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request) {
    wrap := middleware.NewWrapResponseWriter(w,r.ProtoMajor)
    var captured bytes.Buffer
    wrap.Tee(&captured)
    if discard { wrap.Discard() }
    if informational { wrap.WriteHeader(http.StatusEarlyHints) }
    flush := func() {
     if controller {
      if err := http.NewResponseController(wrap).Flush(); err != nil { t.Error(err) }
     } else { wrap.(http.Flusher).Flush() }
    }
    flush()
    if _,err := wrap.Write([]byte("body")); err != nil { t.Error(err) }
    flush()
    if wrap.Status()!=200 || wrap.BytesWritten()!=4 || captured.String()!="body" {
     t.Errorf("wrapper: status=%d bytes=%d capture=%q",wrap.Status(),wrap.BytesWritten(),captured.String())
    }
    w.Header().Set("X-Final","yes")
    if discard { w.WriteHeader(http.StatusAccepted) }
    _,_ = w.Write([]byte("replacement"))
   }))
   s.EnableHTTP2=h2
   s.StartTLS()
   defer s.Close()
   req,err:=http.NewRequest(method,s.URL,nil)
   if err!=nil { t.Fatal(err) }
   resp,err:=s.Client().Do(req)
   if err!=nil { t.Fatal(err) }
   defer resp.Body.Close()
   body,err:=io.ReadAll(resp.Body)
   if err!=nil { t.Fatal(err) }
   wantStatus,wantHeader,wantBody:=200,"","bodyreplacement"
   if discard { wantStatus,wantHeader,wantBody=202,"yes","replacement" }
   if method=="HEAD" { wantBody="" }
   wantProto:=1
   if h2 { wantProto=2 }
   if resp.ProtoMajor!=wantProto || resp.StatusCode!=wantStatus || resp.Header.Get("X-Final")!=wantHeader || string(body)!=wantBody {
    t.Errorf("got proto=%d status=%d final=%q body=%q; want proto=%d status=%d final=%q body=%q", resp.ProtoMajor,resp.StatusCode,resp.Header.Get("X-Final"),body,wantProto,wantStatus,wantHeader,wantBody)
   }
  })
 }}}}}
}
EOF
GOPROXY=off GOMAXPROCS=2 go test -p=1 ./middleware -run '^TestCrowDiscardFlushIntegration$' -count=1 -v

