cat > tests/crow_boundaries.rs <<'EOF'
fn check(n: u128) {
    let mut b = itoa::Buffer::new();
    assert_eq!(b.format(n), n.to_string());
    let signed = n as i128;
    assert_eq!(b.format(signed), signed.to_string());
}
#[test]
fn chunks_and_random() {
    const D: u128 = 10_000_000_000_000_000;
    for quad in 0..10_000u128 {
        for tail in [0, 1, 999_999_999_999] {
            let chunk = quad * 1_000_000_000_000 + tail;
            check(D + chunk);
            check(D * D + chunk * D + chunk);
        }
    }
    for exponent in 0..=38 {
        let n = 10u128.pow(exponent);
        check(n - 1); check(n); check(n + 1);
    }
    check(u128::MAX); check(i128::MAX as u128); check(i128::MIN as u128);
    let mut n = 0x0123456789abcdef_fedcba9876543210u128;
    for _ in 0..100_000 {
        n ^= n << 13; n ^= n >> 7; n ^= n << 17;
        check(n);
    }
}
EOF
