import http from 'node:http';
import fs from 'node:fs';
import {chromium} from '/opt/browser/node_modules/playwright-core/index.mjs';
const html='<!doctype html><html class="dark"><head><link rel="stylesheet" href="/style.css"><style>:root{--thread-details-panel-width:320px}body{margin:0;background:var(--background);color:var(--foreground)}</style></head><body><div id="root"></div><script src="/app.js"></script></body></html>';
const server=http.createServer((req,res)=>{const f=req.url.split('?')[0];res.setHeader('Content-Type',f.endsWith('.js')?'text/javascript':f.endsWith('.css')?'text/css':'text/html');res.end(f==='/app.js'||f==='/style.css'?fs.readFileSync('.crow-review'+f):html)}).listen(4173,'127.0.0.1');
const browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
const page=await browser.newPage({viewport:{width:1440,height:600}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
try {
 await page.goto('http://127.0.0.1:4173');
 await page.locator('[data-thread-details-card]').waitFor();
 await page.screenshot({path:'/workspace/.crow-review/desktop.png'});
 console.log('desktop card:',await page.locator('[data-thread-details-card]').innerText());
 await page.setViewportSize({width:600,height:600});
 await page.goto('http://127.0.0.1:4173');
 await page.waitForFunction(()=>window.crow);
 const isHead=fs.readFileSync('apps/web/src/components/chat/ThreadDetailsPanel.tsx','utf8').includes('ThreadDetailsPanelHandle');
 if(isHead){
  await page.evaluate(()=>window.crow.openControl('composer.host'));
  await page.getByRole('listbox').waitFor({timeout:5000});
  console.log('closed-card host shortcut opened listbox');
 }else{
  await page.getByRole('button',{name:'Toggle thread details panel'}).click();
  await page.getByRole('combobox',{name:'Run on'}).click();
 }
 await page.screenshot({path:'/workspace/.crow-review/hosts.png'});
 console.log('host options:',await page.getByRole('listbox').innerText());
 await page.getByRole('option',{name:'Remote workstation',exact:true}).click();
 console.log('host selection:',await page.evaluate(()=>window.crow.state()));
 await page.setViewportSize({width:390,height:600});
 await page.goto('http://127.0.0.1:4173/?force');
 await page.getByRole('button',{name:'Toggle thread details panel'}).click();
 await page.locator('[data-thread-details-card]').waitFor();
 console.log('multi-model workspace triggers:',await page.locator('button[data-composer-shortcut="composer.workspace"]').count());
 await page.screenshot({path:'/workspace/.crow-review/multimodel.png'});
 if(errors.length)throw new Error(errors.join('\n'));
}finally{await browser.close();server.close();}
EOF
